cat > src/unpipe.js <<'EOF'
/**
 * Detach a readable stream from every destination it is piped to.
 *
 * Uses the native `readable.unpipe()` (no argument = all destinations).
 * Safe to call on null/undefined, non-readables, already-destroyed
 * streams, or streams with no pipes.
 *
 * @param {import('node:stream').Readable} stream
 * @returns {import('node:stream').Readable} the same stream
 */
export function unpipe(stream) {
  if (!stream) {
    throw new TypeError('argument stream is required');
  }
  if (typeof stream.unpipe === 'function') {
    stream.unpipe();
  }
  return stream;
}
EOF
cat > src/server.js <<'EOF'
import http from 'node:http';
import { PassThrough } from 'node:stream';
import { fileURLToPath } from 'node:url';
import { unpipe } from './unpipe.js';

export function createServer() {
  return http.createServer((req, res) => {
    // Example: tee the request body to a side-channel while echoing it back.
    const audit = new PassThrough();
    audit.resume();

    req.pipe(res);
    req.pipe(audit);

    // If the client goes away, detach the request from all destinations
    // so nothing keeps writing to a dead response.
    res.on('close', () => {
      if (!res.writableFinished) unpipe(req);
    });
  });
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  createServer().listen(port, () => {
    console.log(`listening on http://localhost:${port}`);
  });
}
EOF
cat > test/unpipe.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { PassThrough, Readable } from 'node:stream';
import { unpipe } from '../src/unpipe.js';

test('unpipes from all destinations', () => {
  const src = new PassThrough();
  const dests = [new PassThrough(), new PassThrough(), new PassThrough()];
  dests.forEach((d) => src.pipe(d));
  assert.equal(src.listenerCount('data'), 1);

  let unpiped = 0;
  dests.forEach((d) => d.on('unpipe', () => unpiped++));

  assert.equal(unpipe(src), src);
  assert.equal(unpiped, 3);
  assert.equal(src.listenerCount('data'), 0);
});

test('data written after unpipe does not reach former destinations', async () => {
  const src = new PassThrough();
  const dest = new PassThrough();
  src.pipe(dest);
  unpipe(src);

  let got = false;
  dest.on('data', () => { got = true; });
  src.write('hello');
  await new Promise((r) => setImmediate(r));
  assert.equal(got, false);
});

test('is a no-op with no destinations, and is idempotent', () => {
  const src = Readable.from([]);
  unpipe(src);
  unpipe(src);
});

test('throws without a stream', () => {
  assert.throws(() => unpipe(), TypeError);
});
EOF
cat > test/server.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from '../src/server.js';

test('echoes the request body', async () => {
  const server = createServer().listen(0);
  await new Promise((r) => server.once('listening', r));
  const { port } = server.address();
  try {
    const res = await fetch(`http://localhost:${port}`, { method: 'POST', body: 'ping' });
    assert.equal(await res.text(), 'ping');
  } finally {
    server.close();
  }
});
EOF
npm test 2>&1 | tail -15

